package org.apache.commons.compress.archivers.zip;

import java.io.*;
import java.io.File;
import java.math.*;
import java.util.*;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Date;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.zip.ZipException;
import org.apache.commons.compress.archivers.ArchiveEntry;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class ZipArchiveEntry_equals_TriageGen1Test {

    @Test
    public void testEquals_SameInstance() {
        ZipArchiveEntry entry = new ZipArchiveEntry("test.txt");
        assertTrue(entry.equals(entry));
    }

    @Test
    public void testEquals_NullObject() {
        ZipArchiveEntry entry = new ZipArchiveEntry("test.txt");
        assertFalse(entry.equals(null));
    }

    @Test
    public void testEquals_DifferentClass() {
        ZipArchiveEntry entry = new ZipArchiveEntry("test.txt");
        Object other = "not a zip entry";
        assertFalse(entry.equals(other));
    }

    @Test
    public void testEquals_NameMismatch() {
        ZipArchiveEntry entry1 = new ZipArchiveEntry("a.txt");
        ZipArchiveEntry entry2 = new ZipArchiveEntry("b.txt");
        assertFalse(entry1.equals(entry2));
    }

    @Test
    public void testEquals_NameNull_OtherNameNotNull() {
        // Using reflection or a subclass if name is protected/private to simulate null name
        // Since the constructor takes a String, we rely on the internal state
        ZipArchiveEntry entry1 = new ZipArchiveEntry(null);
        ZipArchiveEntry entry2 = new ZipArchiveEntry("a.txt");
        assertFalse(entry1.equals(entry2));
    }

    @Test
    public void testEquals_NameNull_OtherNameNull() {
        ZipArchiveEntry entry1 = new ZipArchiveEntry(null);
        ZipArchiveEntry entry2 = new ZipArchiveEntry(null);
        // They should be equal if other fields match
        assertTrue(entry1.equals(entry2));
    }

    @Test
    public void testEquals_CommentLogic() {
        ZipArchiveEntry entry1 = new ZipArchiveEntry("test.txt");
        entry1.setComment("hello");

        ZipArchiveEntry entry2 = new ZipArchiveEntry("test.txt");
        entry2.setComment("hello");
        assertTrue(entry1.equals(entry2));

        // Test null comment treated as empty string
        ZipArchiveEntry entry3 = new ZipArchiveEntry("test.txt");
        entry3.setComment(null);

        ZipArchiveEntry entry4 = new ZipArchiveEntry("test.txt");
        entry4.setComment("");

        // Based on code: if myComment is null, it becomes ""; if otherComment is null, it becomes ""
        // So null and "" should be equal.
        assertTrue(entry3.equals(entry4));
    }

    @Test
    public void testEquals_ExtraDataMismatch() {
        ZipArchiveEntry entry1 = new ZipArchiveEntry("test.txt");
        entry1.setExtra(new byte[]{1, 2, 3});

        ZipArchiveEntry entry2 = new ZipArchiveEntry("test.txt");
        entry2.setExtra(new byte[]{1, 2, 4});

        assertFalse(entry1.equals(entry2));
    }

    @Test
    public void testEquals_GPBMismatch() {
        ZipArchiveEntry entry1 = new ZipArchiveEntry("test.txt");
        entry1.setGeneralPurposeBit(GeneralPurposeBit.DEFLATED);

        ZipArchiveEntry entry2 = new ZipArchiveEntry("test.txt");
        // Default is likely different or we can set it specifically
        entry2.setGeneralPurposeBit(GeneralPurposeBit.STORED);

        assertFalse(entry1.equals(entry2));
    }

    @Test
    public void testEquals_Success() {
        ZipArchiveEntry entry1 = new ZipArchiveEntry("test.txt");
        entry1.setComment("comment");
        entry1.setExtra(new byte[]{0x01});
        entry1.setGeneralPurposeBit(GeneralPurposeBit.DEFLATED);

        ZipArchiveEntry entry2 = new ZipArchiveEntry("test.txt");
        entry2.setComment("comment");
        entry2.setExtra(new byte[]{0x01});
        entry2.setGeneralPurposeBit(GeneralPurposeBit.DEFLATED);

        assertTrue(entry1.equals(entry2));
    }
}
